"kernel vec4 naturalHairColor(
    __sample image,
    vec4 targetColor
) {
    vec3 orig = image.rgb;
    // Native luminance of original hair pixel (Rec. 709 / sRGB)
    float Y0 = dot(orig, vec3(0.2126, 0.7152, 0.0722));

    vec3 targetRGB = targetColor.rgb;
    float Ys = dot(targetRGB, vec3(0.2126, 0.7152, 0.0722));

    float maxC = max(targetRGB.r, max(targetRGB.g, targetRGB.b));
    float minC = min(targetRGB.r, min(targetRGB.g, targetRGB.b));
    float sat = (maxC > 0.001) ? (maxC - minC) / maxC : 0.0;

    vec3 colored;
    if (sat < 0.05) {
        // Natural Black hair:
        // Rather than a flat silhouette, scales luminance naturally
        // preserving all fine strand shadows, midtones, and specular highlights
        float darkY = Y0 * 0.45;
        float sheen = smoothstep(0.25, 0.8, Y0) * 0.25;
        colored = vec3(clamp(darkY + sheen, 0.0, 1.0));
    } else {
        // Chromatic hair colors (Burgundy, Brown, Caramel, Honey):
        // 1. Exact luminance-preserving chromaticity modulation:
        // Combine selectedColor hue/chroma with ORIGINAL luminance
        vec3 chromaRatio = targetRGB / max(Ys, 0.01);

        // Hair pigment reaches peak richness in midtones and stays natural
        // Avoid blowing out high-luminance strands or highlights into neon paint
        vec3 dyed = chromaRatio * min(Y0, Ys * 1.6 + 0.15) + max(0.0, Y0 - (Ys * 1.6 + 0.15));

        // 2. Specular highlight protection:
        // Highlights on hair reflect ambient white light off the cuticle surface
        float highlight = smoothstep(0.35, 0.75, Y0);
        colored = mix(dyed, orig, highlight * 0.85);
        colored = clamp(colored, 0.0, 1.0);
    }
    return vec4(colored, image.a);
}"

"kernel vec4 teethLumaGate(__sample pixel, __sample mask) {
    float luma = dot(pixel.rgb, vec3(0.299, 0.587, 0.114));
    // Teeth are brighter than dark oral cavity & tongue.
    // Smooth transition between 0.20 and 0.40 luminance:
    float factor = smoothstep(0.20, 0.40, luma);
    float m = mask.r * factor;
    return vec4(m, m, m, m);
}"
